<script setup lang="ts">
import {ref,onMounted} from 'vue';
import type {World} from '../../../packages/shared/src/types';
const props=defineProps<{world:World}>(),emit=defineEmits(['updated']);
const list=ref<any[]>([]),error=ref(''),message=ref(''),selected=ref(''),budget=ref(.5),maxCalls=ref(50),scope=ref('default');
const form=ref({id:'',name:'',baseUrl:'',model:'',apiKey:'',enabled:true,protocol:'OPENAI',timeoutMs:10000,inputPrice:0,outputPrice:0});
async function api(path:string,b?:any){const r=await fetch(path,{method:b?'POST':'GET',headers:{'content-type':'application/json'},body:b?JSON.stringify(b):undefined});const j=await r.json();if(!r.ok)throw new Error(j.message);return j;}
async function load(){try{list.value=await api('/api/model-providers');}catch(e:any){error.value=e.message;}}
async function save(){try{await api('/api/model-providers',form.value);form.value.apiKey='';message.value='供应商已保存，密钥仅存于服务器';error.value='';await load();}catch(e:any){error.value=e.message;}}
async function test(id:string){try{const r=await api(`/api/model-providers/${id}/test`,{});message.value=`连接成功 · ${Math.round(r.usage.latency)} ms`;error.value='';}catch(e:any){error.value=e.message;}}
async function bind(){try{const existing=props.world.modelPolicies??{default:{providers:[],dailyBudget:.5,maxCalls:50},residents:{},purposes:{}};const p=structuredClone(existing),value={providers:selected.value?[selected.value]:[],dailyBudget:budget.value,maxCalls:maxCalls.value};if(scope.value==='default')p.default=value;else if(scope.value.startsWith('purpose:'))p.purposes[scope.value.slice(8)]=value;else p.residents[scope.value]=value;emit('updated',await api(`/api/worlds/${props.world.id}/model-policies`,{...p,key:crypto.randomUUID(),expectedVersion:props.world.version}));message.value='模型策略已更新';}catch(e:any){error.value=e.message;}}
onMounted(load);
</script>
<template><div><h2>模型中心</h2><p>无配置时使用规则。外部模型只提出建议，不能修改世界。</p><form @submit.prevent="save"><label>标识<input v-model="form.id" required></label><label>供应商名称<input v-model="form.name" required></label><label>Base URL<input v-model="form.baseUrl" placeholder="https://…/v1" required></label><label>模型<input v-model="form.model" required></label><label>API Key<input v-model="form.apiKey" type="password" autocomplete="off" placeholder="留空保留现有密钥"></label><label><input v-model="form.enabled" type="checkbox">启用</label><button>安全保存</button></form><div v-for="p in list" class="notice"><strong>{{p.name}}</strong><p>{{p.model}} · {{p.enabled?'启用':'停用'}} · {{p.hasKey?'已存密钥':'无密钥'}}</p><button @click="form={...p,apiKey:''}">编辑</button> <button @click="test(p.id)">测试连接</button></div><h3>策略与预算</h3><select v-model="scope"><option value="default">世界默认</option><option v-for="p in ['planning','dialogue','summary','intent','embedding','decision']" :value="'purpose:'+p">用途 {{p}}</option><option v-for="r in world.residents" :value="r.id">{{r.name}}</option></select><select v-model="selected"><option value="">纯规则</option><option v-for="p in list" :value="p.id">{{p.name}}</option></select><label>每日费用上限<input v-model.number="budget" type="number" step=".01" min="0"></label><label>每日调用上限<input v-model.number="maxCalls" type="number" min="0"></label><button @click="bind">应用策略</button><p>{{message}}</p><p class="error">{{error}}</p><h3>最近调用</h3><p v-for="u in (world.aiUsage??[]).slice(-10).reverse()">{{u.provider}} · {{u.input}}/{{u.output}} token · {{u.cost.toFixed(6)}} · {{u.error??'成功'}}</p></div></template>
